import { transform } from 'esbuild';
import { randomBytes } from 'node:crypto';
import { readFileSync, realpathSync, statSync } from 'node:fs';
import { join, posix } from 'node:path';
import { ASSET_LOADERS, docsPathToRelative, inside, URL_LIKE } from './bundle.js';
const SCRIPT = /\.[cm]?[jt]sx?$/;
const SCRIPT_SPECIFIER = /\b(?:from|import)\s*\(?\s*(['"])([^'"\n]+)\1|\brequire\s*\(\s*(['"])([^'"\n]+)\3/g;
const CSS_SPECIFIER = /@import\s+(?:url\(\s*)?(['"]?)([^'")\s;]+)\1|\burl\(\s*(['"]?)([^'")\s]+)\3\s*\)/g;
const LOCAL_SCRIPT_SPECIFIER = /^\.{0,2}\/(?!\/)/;
const RUNTIME_PATH_CALL = /_(import|require)\(\s*(?:\/\*[\s\S]*?\*\/\s*)*(`\.{0,2}\/(?!\/)[^`]*?\$\{[^`]*`|(?<q>[`'"])\.{0,2}\/(?!\/)[^`'"\n]*\k<q>\s*\+[^)\n]*)/g;
const EXTENSIONS = ['.tsx', '.ts', '.jsx', '.js', '.css', '.json'];
const SCRIPT_CANDIDATES = ['', ...EXTENSIONS, ...EXTENSIONS.map((ext) => `/index${ext}`)];
const PACKAGE_MANAGER_ROOT_FILES = new Set([
    '/package-lock.json',
    '/npm-shrinkwrap.json',
    '/pnpm-lock.yaml',
    '/pnpm-workspace.yaml',
    '/.pnpmfile.cjs',
    '/.pnpmfile.mjs',
    '/yarn.lock',
    '/.yarnrc',
    '/.yarnrc.yml',
]);
export function packageManagerFileProblems(files) {
    return Object.keys(files)
        .filter((path) => {
        const segments = path.split('/').filter((seg) => seg !== '.');
        return segments.includes('.npmrc') || PACKAGE_MANAGER_ROOT_FILES.has(segments.join('/'));
    })
        .sort()
        .map((path) => ({
        level: 'error',
        code: 'local-file-package-manager',
        message: `Snippets cannot import ${path}: hosted builds reject package manager files at the docs root and .npmrc files.`,
    }));
}
export function isLocalInputPath(path) {
    const extension = posix.extname(path).toLowerCase();
    return (SCRIPT.test(extension) ||
        EXTENSIONS.includes(extension) ||
        Object.prototype.hasOwnProperty.call(ASSET_LOADERS, extension));
}
function specifiers(source, pattern) {
    return [...source.matchAll(pattern)].flatMap((m) => m[2] ?? m[4] ?? []);
}
function text(content) {
    return typeof content === 'string' ? content : new TextDecoder().decode(content);
}
function loaderFor(path) {
    return path.endsWith('tsx') ? 'tsx' : path.endsWith('ts') ? 'ts' : 'jsx';
}
export async function runtimeImports(files, islands) {
    const sources = [
        ...Object.entries(files)
            .filter(([path]) => SCRIPT.test(path))
            .map(([path, content]) => ({ where: path, loader: loaderFor(path), source: text(content) })),
        ...islands.map((i) => ({
            where: `island ${i.id} (${i.pagePath})`,
            loader: 'jsx',
            source: i.module,
        })),
    ];
    const mark = `__mint${randomBytes(8).toString('hex')}`;
    const calls = new RegExp(mark + RUNTIME_PATH_CALL.source, 'g');
    const found = await Promise.all(sources.map(async ({ where, loader, source }) => {
        const code = await transform(source, {
            loader,
            supported: { 'dynamic-import': false },
            define: { require: `${mark}_require` },
        })
            .then((r) => transform(r.code, { loader: 'js', define: { require: `${mark}_import` } }))
            .then((r) => r.code, () => '');
        return [...code.matchAll(calls)].map((m) => `${where}: ${m[1]}(${m[2].replace(/\s+/g, ' ')}) builds its path at runtime; import each file statically.`);
    }));
    return found.flat();
}
export function collectLocalFiles(input) {
    const files = { ...input.snippetFiles };
    let root;
    try {
        root = realpathSync(input.docsRoot);
    }
    catch {
        root = undefined;
    }
    const read = (rel) => {
        if (!root || rel.split('/').includes('node_modules'))
            return undefined;
        try {
            const real = realpathSync(join(root, rel));
            const stat = statSync(real);
            const linked = input.rejectHardLinks === true && stat.nlink > 1;
            return inside(root, real) && stat.isFile() && !linked
                ? new Uint8Array(readFileSync(real))
                : undefined;
        }
        catch {
            return undefined;
        }
    };
    const locate = (specifier, importer) => {
        if (specifier.startsWith('/'))
            return docsPathToRelative(specifier.replace(/\/+$/, ''));
        const rel = posix.normalize(posix.join(posix.dirname(importer), specifier)).replace(/\/+$/, '');
        return rel === '.' || rel === '..' || rel.startsWith('../') ? undefined : rel;
    };
    const follow = (specifier, importer, candidates) => {
        for (const spec of new Set([specifier, specifier.replace(/[?#].*$/, '')])) {
            const rel = locate(spec, importer);
            if (rel === undefined)
                continue;
            for (const suffix of candidates) {
                const path = `/${rel}${suffix}`;
                if (files[path] !== undefined)
                    return path;
                const data = read(`${rel}${suffix}`);
                if (data) {
                    files[path] = data;
                    return path;
                }
                input.onMissing?.(path);
            }
        }
        return undefined;
    };
    const roots = [
        ...(input.provider ? [input.provider] : []),
        ...input.islands.flatMap((i) => specifiers(i.module, SCRIPT_SPECIFIER).filter((s) => /^\/(?!\/)/.test(s))),
    ].flatMap((specifier) => follow(specifier, '', SCRIPT_CANDIDATES) ?? []);
    const stack = [...Object.keys(input.snippetFiles), ...roots];
    const seen = new Set();
    while (stack.length > 0) {
        const path = stack.pop();
        const rel = docsPathToRelative(path);
        const content = files[path];
        if (seen.has(path) || rel === undefined || content === undefined)
            continue;
        seen.add(path);
        const css = rel.endsWith('.css');
        if (!css && !SCRIPT.test(rel))
            continue;
        for (const specifier of specifiers(text(content), css ? CSS_SPECIFIER : SCRIPT_SPECIFIER)) {
            if (css ? URL_LIKE.test(specifier) : !LOCAL_SCRIPT_SPECIFIER.test(specifier))
                continue;
            const found = follow(specifier, rel, css ? [''] : SCRIPT_CANDIDATES);
            if (found)
                stack.push(found);
        }
    }
    return files;
}
